/* 0073_niche_preview_without_reading_everything.sql, flattened for the Supabase SQL editor. Generated by scripts/flatten-migration.mjs - do not edit this file, edit the migration and run the script again. One statement per line, no line comments, nothing to lose to a newline. The commentary lives in the migration itself. */
create or replace function public.marketplace_niche_preview( p_niche text, p_limit integer default 6 ) returns table ( id uuid, total bigint, countries bigint ) language sql stable set search_path = public as $$ with matched as ( select w.id, w.domain_rating, case when w.country_source = 'default' then null else w.country_code end as country from public.websites w left join public.categories pc on pc.id = w.primary_category_id where w.status = 'active' and ( coalesce(pc.slug, 'technology') = p_niche or exists ( select 1 from public.website_categories wc join public.categories c on c.id = wc.category_id where wc.website_id = w.id and c.slug = p_niche ) ) ), counted as ( select count(*) as total, count(distinct country) filter (where country is not null) as countries from matched ), ordered as ( select m.id, row_number() over (order by m.domain_rating desc, m.id asc) - 1 as position from matched m ) select ordered.id, counted.total, counted.countries from ordered cross join counted where ordered.position % greatest(1, counted.total / greatest(coalesce(p_limit, 6), 1)) = 0 order by ordered.position limit greatest(1, least(coalesce(p_limit, 6), 24)); $$;
comment on function public.marketplace_niche_preview(text, integer) is 'A niche landing page''s sample and counts. Replaces paging through every active listing with five embedded tables to show six rows.';
revoke all on function public.marketplace_niche_preview(text, integer) from public;
grant execute on function public.marketplace_niche_preview(text, integer) to anon, authenticated, service_role;
